export const MONUMENTS = JSON.parse("[{\"id\":\"n7025578620\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Акимову\",\"x\":-735.5,\"z\":-193.2,\"subject\":\"Q1185061\",\"inscription\":\"Здесь в 1935–1939 и 1956–1968 годах работал выдающийся режиссёр и художник Николай Павлович Акимов\"},{\"id\":\"n7804519467\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Струве\",\"x\":-1711.7,\"z\":-1116.5,\"subject\":\"Q647712\",\"inscription\":\"Здесь с 1948 по 1965 год жил выдающийся историк и востоковед, академик Василий Васильевич Струве\"},{\"id\":\"n5546742967\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Raphael Morghen\",\"x\":-1867.9,\"z\":-991.7,\"subject\":\"Q2275991\"},{\"id\":\"n5546742968\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Winckelmann\",\"x\":-1863.5,\"z\":-995.1,\"subject\":\"Q57280\"},{\"id\":\"n5553493449\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Dioscorides\",\"x\":-1842.3,\"z\":-1012.2},{\"id\":\"n5553493450\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Pheidon\",\"x\":-1853.6,\"z\":-1027},{\"id\":\"n5553493451\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Pichler\",\"x\":-1842.9,\"z\":-1007},{\"id\":\"n5553493452\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Pyrgoteles\",\"x\":-1854.7,\"z\":-998.1,\"subject\":\"Q1243453\"},{\"id\":\"n5661727654\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. Б. Пиотровскому\",\"x\":-1695.8,\"z\":-1032,\"subject\":\"Q481605\",\"inscription\":\"В этом доме жил директор Эрмитажа, академик Борис Борисович Пиотровский (1908–1990)\"},{\"id\":\"n5661728701\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Собчаку\",\"x\":-1752.8,\"z\":-982.9,\"subject\":\"Q334294\",\"inscription\":\"В этом доме жил с 1990 по 2000 год Анатолий Александрович Собчак — первый мэр Санкт-Петербурга\"},{\"id\":\"n6482673282\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Пушкинское место\",\"x\":-1686,\"z\":-986.5,\"subject\":\"Q7200\",\"inscription\":\"В этом доме 29 января 1837 года скончался Александр Сергеевич Пушкин\"},{\"id\":\"n8901819748\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Н. Рахманову\",\"x\":-1195.8,\"z\":-1078.3,\"subject\":\"Q4391162\",\"inscription\":\"В этом доме с 1950 по 1988 год жил писатель Леонид Николаевич Рахманов\"},{\"id\":\"n8901825369\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ю. П. Герману\",\"x\":-1210,\"z\":-1114.9,\"subject\":\"Q4137236\",\"inscription\":\"В этом доме с 1948 по 1967 год жил выдающийся советский писатель Юрий Павлович Герман\"},{\"id\":\"n8901831107\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Л. Шиллингу фон Канштадту\",\"x\":-1198.6,\"z\":-1090.1,\"subject\":\"Q717731\",\"inscription\":\"Здесь жил и умер русский изобретатель электро-магнитного телеграфа барон Павел Львович Шиллинг фон Канштадт, родился 5 апреля 1786 г., умер 25 июля 1837 г.\"},{\"id\":\"n8901831538\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. В. Баранову\",\"x\":-1204.1,\"z\":-1104.3,\"subject\":\"Q4077759\",\"inscription\":\"Здесь жил и работал Народный архитектор СССР, академик архитектуры, главный архитектор Ленинграда с 1938 по 1950 год Николай Варфоломеевич Баранов\"},{\"id\":\"n9023403705\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. Л. Хетагурову\",\"x\":-1571.9,\"z\":-1099.6,\"subject\":\"Q368956\",\"inscription\":\"В этом доме жил основоположник осетинского литературного языка, выдающийся поэт и художник, революционный демократ Коста Леванович Хетагуров\"},{\"id\":\"n9749742039\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. В. Самойлову\",\"x\":-1286.7,\"z\":-1106.6,\"subject\":\"Q4406715\",\"inscription\":\"В этом доме с 1898 года жил и в 1931 году умер заслуженный артист РСФСР Павел Васильевич Самойлов\"},{\"id\":\"n1948007159\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Порфировая ваза\",\"x\":-814,\"z\":-1057.1,\"startDate\":\"1839\",\"wikidata\":\"Q4373478\",\"wikipedia\":\"ru:Порфировая ваза\"},{\"id\":\"n2513007719\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Чижик-Пыжик\",\"x\":-741.5,\"z\":-1033.8,\"h\":0.11,\"material\":\"bronze\",\"startDate\":\"1994-11-19\",\"wikidata\":\"Q16270744\",\"wikipedia\":\"ru:Памятник Чижику-Пыжику\"},{\"id\":\"n5736313317\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Героической обороне полуострова Ханко\",\"x\":-513.3,\"z\":-1114.6,\"subject\":\"Q384680\",\"inscription\":\"Слава великому советскому народу! Доска воздвигнута в честь героической обороны полуострова Ханко (22 июня — 2 декабря 1941 г.) в Великой Отечественной войне 1941—1945 гг. Слава мужественным защитникам полуострова Ханко!\"},{\"id\":\"n5736313318\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Лягину\",\"x\":-569.3,\"z\":-1096.1,\"subject\":\"Q4272485\",\"inscription\":\"В этом доме с 1934 по 1939 годы жил Герой Советского Союза чекист-разведчик Виктор Александрович Лягин, руководитель подпольного центра в городе Николаеве в годы Великой Отечественной войны\"},{\"id\":\"n5736313320\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ли Бом Джину\",\"x\":-592.5,\"z\":-1092.7,\"inscription\":\"Здесь жил и работал с 1901 по 1905 год первый постоянный чрезвычайный и полномочный посланник Кореи в Российской империи принц Ли Бом Джин\"},{\"id\":\"n8777372349\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. А. Столыпину\",\"x\":-632.1,\"z\":-1001.1,\"subject\":\"Q138487\",\"inscription\":\"Председатель совета министров, министр внутренних дел Российской Империи Петр Аркадьевич Столыпин работал в этом здании в 1906-1911 годах\"},{\"id\":\"n8960771420\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Центральному бюро петербургских профрабсоюзов\",\"x\":-661.9,\"z\":-1107.1,\"inscription\":\"Здесь в 1905 г. помещалось первое Центральное бюро петербургских профессиональных рабочих союзов, заложившее в своей работе основание Ленинградскому совету профсоюзов\"},{\"id\":\"n8960784054\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Первому съезду русских деятелей профессионального и технического образования\",\"x\":-623.8,\"z\":-1112.5,\"inscription\":\"В этом доме с 26 декабря 1889 г. по 6 января 1890 г. проходил I-ый съезд русских деятелей профессионального и технического образования\"},{\"id\":\"n8960784248\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-568.8,\"z\":-1116.7,\"material\":\"marble\",\"inscription\":\"Сей храм воздвигнут в царствование императора Петра Великого в 1721 году в благодарение Богу за дарованные нам морские победы над шведами в день Святого Великомученика Пантелеймона 27 июля при Гангуте в 1714 году и при Гренгамне в 1720 году.\"},{\"id\":\"n14135508014\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-559.2,\"z\":-1117.1,\"material\":\"marble\"},{\"id\":\"n14135508015\",\"kind\":\"artwork\",\"sub\":\"relief\",\"x\":-577.8,\"z\":-1115.1},{\"id\":\"n1473999380\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Пегас\",\"x\":-1493.4,\"z\":-949.5,\"artist\":\"Василий Николаевич Аземша\"},{\"id\":\"n3517261962\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"А. С. Пушкину\",\"x\":-1661.5,\"z\":-956.3,\"startDate\":\"1952-10-05\",\"subject\":\"Q7200\",\"inscription\":\"Пушкину 1950\"},{\"id\":\"n5979536414\",\"kind\":\"artwork\",\"x\":-1546.1,\"z\":-910.3},{\"id\":\"n6484540298\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Е. Баснеру\",\"x\":-1735.9,\"z\":-933,\"subject\":\"Q652990\",\"inscription\":\"В этом доме жил и работал композитор Вениамин Ефимович Баснер\"},{\"id\":\"n8960799265\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. С. Тургеневу\",\"x\":-1548.7,\"z\":-788.1,\"subject\":\"Q42831\",\"inscription\":\"В этом доме с 1858 г. по 1860 г. жил великий русский писатель Иван Сергеевич Тургенев\"},{\"id\":\"n13868150581\",\"kind\":\"artwork\",\"x\":-1562.4,\"z\":-823.1,\"description\":\"Каменная маска на стена\"},{\"id\":\"n1412456535\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"К. И. Росси\",\"x\":-971.7,\"z\":-937.2,\"subject\":\"Q619584\"},{\"id\":\"n1412626295\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"А. А. Иванов\",\"x\":-980.5,\"z\":-926.2,\"subject\":\"Q76829\"},{\"id\":\"n1412626297\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"К. П. Брюллов\",\"x\":-967.5,\"z\":-924.1,\"subject\":\"Q4768\"},{\"id\":\"n4428331026\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Павел I\",\"x\":-766.1,\"z\":-907.4,\"startDate\":\"2003-05-28\",\"subject\":\"Q15189\"},{\"id\":\"n8777409349\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Ф. Громову\",\"x\":-558.1,\"z\":-888.5,\"subject\":\"Q4150200\",\"inscription\":\"В этом доме жил благотворитель и меценат, русский купец Василий Федулович Громов (1798-1869)\"},{\"id\":\"n8777411699\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-584.1,\"z\":-926.8,\"inscription\":\"Здесь на квартире декабриста Николая Ивановича Тургенева в 1819–1824 годах проходили совещания тайных декабристских обществ\"},{\"id\":\"n8777424856\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. И. Пыляеву\",\"x\":-559.6,\"z\":-890.7,\"subject\":\"Q4385280\",\"inscription\":\"Михаил Иванович Пыляев (1842-1899) историк, краевед Петербурга жил в этом доме\"},{\"id\":\"n1473999381\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Ваза\",\"x\":-1564,\"z\":-658.9},{\"id\":\"n1473999382\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Ваза\",\"x\":-1559.7,\"z\":-677.8},{\"id\":\"n6484480146\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ю. П. Спегальскому\",\"x\":-1404.2,\"z\":-659.7,\"subject\":\"Q4430992\",\"inscription\":\"В этом доме с 1948 по 1968 год жил архитектор, художник, реставратор, крупнейший исследователь древнего Пскова Юрий Павлович Спегальский\"},{\"id\":\"n6489483482\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"газете «Правда»\",\"x\":-1752.4,\"z\":-659.5,\"subject\":\"Q183644\"},{\"id\":\"n8960794629\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Рылову\",\"x\":-1570.6,\"z\":-692.4,\"subject\":\"Q3623704\",\"inscription\":\"В этом доме с 1929 по 1939 год жил Заслуженный деятель искусств РСФСР художник Аркадий Александрович Рылов\"},{\"id\":\"n8977980682\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Я. Шишкову\",\"x\":-1365.4,\"z\":-591.9,\"subject\":\"Q320653\",\"inscription\":\"В этом доме жил и работал 1941-1942 г.г. Вячеслав Яковлевич Шишков.\"},{\"id\":\"n8977984763\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Рождественскому\",\"x\":-1343.4,\"z\":-679.5,\"subject\":\"Q1322306\",\"inscription\":\"В этом доме в 1949-1977 годах жил и работал поэт Всеволод Александрович Рождественский\"},{\"id\":\"n8977993511\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. М. Зощенко\",\"x\":-1359.6,\"z\":-603.4,\"subject\":\"Q360507\",\"inscription\":\"В этом доме в 1934-1958 годах жил и работал писатель Михаил Михайлович Зощенко\"},{\"id\":\"n8977994240\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. М. Саянову\",\"x\":-1412.9,\"z\":-602.2,\"subject\":\"Q4409624\",\"inscription\":\"В этом доме с 1934 по 1959 г. жил писатель Виссарион Михайлович Саянов\"},{\"id\":\"n8984278540\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-1806.3,\"z\":-683.4,\"subject\":\"Q1394\",\"inscription\":\"Здесь, в бывшем здании Народного комиссариата финансов, в ночь на 14 декабря 1917 года В. И. Ленин провел совещание по подготовке национализации частных банков, которая была осуществлена утром под его руководством\"},{\"id\":\"n9296819779\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1356.4,\"z\":-618.3},{\"id\":\"n1041154862\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Пётр I\",\"x\":-712.2,\"z\":-756.9,\"material\":\"bronze\",\"startDate\":\"1800\",\"subject\":\"Q8479\",\"artist\":\"Бартоломео Карло Растрелли\",\"inscription\":\"Прадеду — правнук\",\"wikidata\":\"Q4343303\",\"wikipedia\":\"ru:Памятник Петру I (Михайловский замок)\",\"heritage\":\"2\"},{\"id\":\"n6580613995\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Об учреждении Русского музея\",\"x\":-1041.7,\"z\":-621,\"material\":\"stone\"},{\"id\":\"n7080782987\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-1056.4,\"z\":-671.7,\"material\":\"stone\"},{\"id\":\"n7110915362\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Тяговая подстанция № 11 «Центральная»\",\"x\":-583.4,\"z\":-762.9,\"inscription\":\"Тяговая подстанция «Центральная» (№ 11), обеспечившая восстановление трамвайного движения в блокадном Ленинграде. Построена в 1931–1933 гг., перестраивалась в 1-й половине 1950-х гг.\"},{\"id\":\"n7110915363\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Подвигу трамвайщиков блокадного Ленинграда\",\"x\":-575.5,\"z\":-751.3,\"inscription\":\"Подвигу трамвайщиков блокадного Ленинграда. После суровой зимы 1941–1942 года эта тяговая подстанция дала энергию в сеть и обеспечила движение возрожденного трамвая.\"},{\"id\":\"n10180478942\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-1078.5,\"z\":-676.7,\"material\":\"stone\"},{\"id\":\"n2487866571\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"К. Д. Ушинскому\",\"x\":-1778,\"z\":-239.2,\"startDate\":\"1961-06-30\",\"artist\":\"В. В. Лишев\"},{\"id\":\"n3200350778\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"И. В. Гёте\",\"x\":-1525.2,\"z\":-447.8,\"startDate\":\"1999-09-30\",\"subject\":\"Q5879\"},{\"id\":\"n6358872948\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1566.5,\"z\":-390.6,\"subject\":\"Q4424524\",\"inscription\":\"В этом доме в 1830х годах находились библиотека и книжная лавка известного книгоиздателя Александра Филипповича Смирдина. Здесь встречались А.С. Пушкин, И.А. Крылов, В.А. Жуковский, Н.В. Гоголь и другие русские писатели и поэты.\"},{\"id\":\"n6450566914\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Апостол Павел\",\"x\":-1543.4,\"z\":-462.5,\"subject\":\"Q9200\"},{\"id\":\"n6450566915\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Апостол Пётр\",\"x\":-1532.5,\"z\":-460,\"subject\":\"Q33923\"},{\"id\":\"n6893148685\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728,\"z\":-373.8,\"material\":\"granite\"},{\"id\":\"n6903094628\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728.3,\"z\":-372.7,\"material\":\"granite\"},{\"id\":\"n10101794031\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. К. Глазунову\",\"x\":-1650.3,\"z\":9.2,\"subject\":\"Q25872\",\"inscription\":\"В этом доме в 1865 году родился и жил по 1928 год выдающийся композитор и музыкальный деятель Александр Константинович Глазунов\"},{\"id\":\"n11030590777\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1667.7,\"z\":9,\"inscription\":\"В этом здании 1 марта 1842 года была открыта первая сберегательная касса России. Первым вкладчиком стал петербуржец Н.А. Кристофари.\"},{\"id\":\"n11030590778\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1713.3,\"z\":96.2,\"inscription\":\"В этом доме кв.№ 25 помещалось в 1905 и 1900 г.г. правление Профессионального союза рабочих Булочно-кондитерского производства организованного явочным порядком 20 ноября с.т./с.т. 1905 г., и работал стачечный комитет руководивший общегубернской стачкой...\"},{\"id\":\"n11238194637\",\"kind\":\"memorial\",\"sub\":\"sculpture\",\"name\":\"Николаю Гумилёву\",\"x\":-1846,\"z\":6.2},{\"id\":\"n12786128897\",\"kind\":\"artwork\",\"sub\":\"mural\",\"name\":\"Ромашки\",\"x\":-1726.8,\"z\":49},{\"id\":\"n13139990414\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Bach\",\"x\":-1555.1,\"z\":-455.2,\"inscription\":\"Бах, Bach, 1685-1750\"},{\"id\":\"n13272985734\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1539.7,\"z\":-383.4},{\"id\":\"n14109137033\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. Тукаю\",\"x\":-1607,\"z\":-121.9},{\"id\":\"n14109137034\",\"kind\":\"memorial\",\"sub\":\"stone\",\"name\":\"С. В. Рахманинову\",\"x\":-1657,\"z\":-90.7},{\"id\":\"n14116247982\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. В. Плеханову\",\"x\":-1555.5,\"z\":-279},{\"id\":\"n318501546\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. И. Кутузову\",\"x\":-1415.4,\"z\":-285.4,\"material\":\"bronze\",\"wikidata\":\"Q21843382\",\"wikipedia\":\"ru:Памятники Кутузову и Барклаю-де-Толли (Санкт-Петербург)\"},{\"id\":\"n318501570\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. Б. Барклаю-де-Толли\",\"x\":-1510.5,\"z\":-314.8,\"material\":\"bronze\",\"startDate\":\"1837-06-15\",\"artist\":\"Б. И. Орловский, С. К. Суханов\",\"wikidata\":\"Q21843382\",\"wikipedia\":\"ru:Памятники Кутузову и Барклаю-де-Толли (Санкт-Петербург)\"},{\"id\":\"n477027518\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"А. С. Пушкину\",\"x\":-1099.1,\"z\":-538.9,\"wikidata\":\"Q9396452\",\"wikipedia\":\"ru:Памятник А. С. Пушкину (Санкт-Петербург, площадь Искусств)\"},{\"id\":\"n747710751\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"Блокадный репродуктор\",\"x\":-787.1,\"z\":-201.9,\"inscription\":\"Здесь, у репродукторов, в дни героической обороны Ленинграда 1941—1944 годов, жители блокадного города слушали сообщения о событиях на фронте\",\"wikidata\":\"Q21026907\",\"wikipedia\":\"ru:Блокадный репродуктор\"},{\"id\":\"n1464061396\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Н. В. Гоголю\",\"x\":-1470,\"z\":-441.6,\"subject\":\"Q43718\",\"wikidata\":\"Q4343129\",\"wikipedia\":\"ru:Памятник Гоголю (Санкт-Петербург, Малая Конюшенная улица)\"},{\"id\":\"n2230915321\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Кот Елисей\",\"x\":-761.9,\"z\":-220.7},{\"id\":\"n2426962446\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Остапу Бендеру\",\"x\":-1267.5,\"z\":-520,\"h\":1.9,\"startDate\":\"2000-07-25\",\"artist\":\"А. С. Чаркин\",\"wikidata\":\"Q25396029\",\"wikipedia\":\"ru:Памятник Остапу Бендеру (Санкт-Петербург)\"},{\"id\":\"n3511128415\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Кошка Василиса\",\"x\":-783.2,\"z\":-218,\"startDate\":\"2000\"},{\"id\":\"n3511128418\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Петербургскому фотографу\",\"x\":-777.5,\"z\":-240,\"startDate\":\"2001-01-25\",\"artist\":\"Б. А. Петров\",\"wikidata\":\"Q4343557\",\"wikipedia\":\"ru:Памятник петербургскому фотографу\"},{\"id\":\"n3698965867\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Дворник\",\"x\":-910.1,\"z\":109.2,\"description\":\"Дворник с лопатой для уборки снега\"},{\"id\":\"n4879158190\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Дом Крылова\",\"x\":-963.9,\"z\":-116.4},{\"id\":\"n5228633808\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. В. Плеханову\",\"x\":-853.8,\"z\":-140.5,\"subject\":\"Q182905;Q2414103\",\"inscription\":\"В этом здании в читальных залах публичной библиотеки в 1874-1880 г.г. работал Г. В. Плеханов — основатель первой русской марксистской организации — группы «Освобождение труда»\"},{\"id\":\"n5507295907\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Сооружению здания для казённой библиотеки\",\"x\":-887,\"z\":-179.4,\"inscription\":\"По высочайше апробованному 1795 года Мая 16 дня плану повелено соорудить здание для Казенной Библиотеки\"},{\"id\":\"n5507566671\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Стасову\",\"x\":-860.2,\"z\":-115.4,\"subject\":\"Q464192\",\"inscription\":\"Здесь с 1855 г. по 1906 г. работал выдающийся деятель русской культуры Владимир Васильевич Стасов\"},{\"id\":\"n5507566672\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Крылову\",\"x\":-858.4,\"z\":-122.4,\"subject\":\"Q191480\",\"inscription\":\"В этом здании с 1812 г. по 1841 г. работал библиотекарем великий русский баснописец Иван Андреевич Крылов\"},{\"id\":\"n5507566674\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-865,\"z\":-175.1,\"subject\":\"Q1394\",\"inscription\":\"В. И. Ленин был постоянным читателем Публичной Библиотеки в 1893–1895 г.г.\"},{\"id\":\"n5664575397\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. И. Петипа\",\"x\":-869.8,\"z\":229.9,\"subject\":\"Q312320\",\"inscription\":\"В этом здании с 1847 по 1905 год служил во славу русского балета Мариус Иванович Петипа\"},{\"id\":\"n5664580331\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Бунину\",\"x\":-912.9,\"z\":79.7,\"subject\":\"Q46602\",\"inscription\":\"В этом здании 21-го ноября 1895 г. состоялось первое литературное выступление великого русского писателя Ивана Алексеевича Бунина. 1870–1953\"},{\"id\":\"n5664580332\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Андрееву\",\"x\":-907.4,\"z\":57.9,\"inscription\":\"20 марта 1888 года в этом здании состоялось первое выступление русского народного оркестра («Кружка любителей игры на балалайках») под управлением его создателя В. В. Андреева\"},{\"id\":\"n5861762343\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. И. Тютчеву\",\"x\":-1056.8,\"z\":-267.4,\"subject\":\"Q37217\",\"inscription\":\"В этом доме жил и работал выдающийся русский поэт Фёдор Иванович Тютчев\"},{\"id\":\"n5861762344\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. М. Сперанскому\",\"x\":-1054.1,\"z\":-266.8,\"subject\":\"Q527037\",\"inscription\":\"В этом доме с 1823 по 1832 год жил выдающийся государственный деятель Михаил Михайлович Сперанский\"},{\"id\":\"n5861762345\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Л. Лазареву\",\"x\":-1094.5,\"z\":-276.3,\"subject\":\"Q4252808\",\"inscription\":\"В этом доме жил выдающийся государственный деятель, просветитель, меценат граф Иван Лазарев\"},{\"id\":\"n6077061649\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. А. Мравинскому\",\"x\":-1107.6,\"z\":-432.1,\"subject\":\"Q320609\",\"inscription\":\"Евгений Мравинский творил здесь LVI лет\"},{\"id\":\"n6077061650\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Исполнению Седьмой (Ленинградской) симфонии Д. Д. Шостаковича\",\"x\":-1102.9,\"z\":-452.2,\"subject\":\"Q261140\",\"inscription\":\"Здесь, в Большом зале Ленинградской филармонии, 9 августа 1942 года оркестр Ленинградского радиокомитета под управлением дирижера К. И. Элиасберга исполнил Седьмую (Ленинградскую) симфонию Д. Д. Шостаковича\"},{\"id\":\"n6484436342\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Павловой\",\"x\":-1174.9,\"z\":-477.7,\"subject\":\"Q151874\",\"inscription\":\"Великая русская балерина Анна Павлова жила в этом доме в 1910 году\"},{\"id\":\"n6484449100\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Ф. Комиссаржевской\",\"x\":-884.9,\"z\":-408.9,\"subject\":\"Q436876\",\"inscription\":\"В этом здании с 1904 г. по 1906 г. помещался Драматический театр, которым руководила выдающаяся русская артистка Вера Фёдоровна Комиссаржевская\"},{\"id\":\"n8822388342\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1041.7,\"z\":-263.7,\"inscription\":\"В этом доме во время блокады Ленинграда с 1941 по 1944 год работала государственная нотариальная контора\"},{\"id\":\"n10238920105\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Далю\",\"x\":-878.2,\"z\":128.3,\"subject\":\"Q326499\",\"inscription\":\"Даль Владимир Иванович, выдающийся русский ученый, составитель Толкового словаря живого великорусского языка, жил и работал в этом доме в 1840-х годах\"},{\"id\":\"n10307371744\",\"kind\":\"memorial\",\"name\":\"Крепим оборону СССР\",\"x\":-1513.1,\"z\":28.1},{\"id\":\"n10951537257\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Крылатый лев\",\"x\":-1479.7,\"z\":17.7,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10951537258\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Крылатый лев\",\"x\":-1481.7,\"z\":19.3,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10951537259\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Крылатый лев\",\"x\":-1466.6,\"z\":36.1,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10951537260\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Крылатый лев\",\"x\":-1464.8,\"z\":34.5,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n11271058953\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Д. Кваренги\",\"x\":-1366.9,\"z\":152.3},{\"id\":\"n11271058962\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Мемориальная доска В.И. Ленину\",\"x\":-1373.2,\"z\":142,\"inscription\":\"В этом здании 8 ноября 1905 года\\nВ. И. ЛЕНИН\\nВыступал на расширенном заседании Петербургского комитета Большевиков с речью об отношении партии к советам рабочих депутатов\"},{\"id\":\"n13237208814\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-925.8,\"z\":-392.4,\"inscription\":\"Вечная слава сотрудникам универмага павшим в боях с немецко-фашистскими захватчиками за свободу и независимость нашей родины в Великой отечественной войне 1941-1945\"},{\"id\":\"n13247901901\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Фредди Меркьюри\",\"x\":-1141.3,\"z\":-288.3,\"subject\":\"Q15869\"},{\"id\":\"n13272985730\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1373.6,\"z\":-531.8},{\"id\":\"n14089810704\",\"kind\":\"artwork\",\"name\":\"Мозаика\",\"x\":-770.6,\"z\":-560.4},{\"id\":\"n14097734446\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"x\":-781,\"z\":179.3},{\"id\":\"w586436085\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Екатерине II\",\"x\":-800.5,\"z\":-104.6,\"subject\":\"Q36450\",\"wikidata\":\"Q2402356\",\"wikipedia\":\"ru:Памятник Екатерине II (Санкт-Петербург)\",\"polys\":[{\"o\":[-793.8,-102.9,-794.3,-101.6,-795,-100.4,-796,-99.3,-797.2,-98.5,-800,-97.7,-801.4,-97.8,-804.2,-98.7,-806.2,-100.7,-806.9,-102,-807.3,-103.4,-807.2,-106.3,-806,-108.9,-805,-109.9,-803.7,-110.7,-802.4,-111.3,-801,-111.5,-798.1,-111.1,-795.7,-109.6,-794.1,-107.2,-793.6,-104.4],\"h\":[]}]}]");
